def _leafwaterpotential_flat_k_impl(num_filter, filter, il, np_, mlcanopy_inst__dpai_profile, mlcanopy_inst__lsc_profile, mlcanopy_inst__lwp_bef_leaf, mlcanopy_inst__lwp_leaf, mlcanopy_inst__ncan_canopy, mlcanopy_inst__psis_soil, mlcanopy_inst__trleaf_leaf, mlcanopy_inst__zs_profile, mlpftcon__capac_spa, patch__itype, clm_varcon__denh2o, clm_varcon__grav, mlclm_varctl__dtime_ml):
    """L260-L332 subroutine (machine-translated)."""
    fp = jnp.int32(0)
    p = jnp.int32(0)
    ic = jnp.int32(0)
    head = jnp.float64(0.0)
    dtime = jnp.float64(0.0)
    y0 = jnp.float64(0.0)
    dy = jnp.float64(0.0)
    a = jnp.float64(0.0)
    b = jnp.float64(0.0)
    head = clm_varcon__denh2o * clm_varcon__grav * F_1PEM06
    dtime = mlclm_varctl__dtime_ml

    def _body_5(fp, _c):
        p, y0, a, b, dy, mlcanopy_inst__lwp_leaf = _c

        def _true_4(_c):
            p, y0, a, b, dy, mlcanopy_inst__lwp_leaf = _c
            p = filter[fp - 1]

            def _body_3(ic, _c):
                y0, a, b, dy, mlcanopy_inst__lwp_leaf = _c

                def _true_2(_c):
                    y0, a, b, dy, mlcanopy_inst__lwp_leaf = _c

                    def _true_1(_c):
                        y0, a, b, dy, mlcanopy_inst__lwp_leaf = _c
                        y0 = mlcanopy_inst__lwp_bef_leaf[p - 1, ic - 1, il - 1]
                        a = mlcanopy_inst__psis_soil[p - 1] - head * mlcanopy_inst__zs_profile[p - 1, ic - 1] - F_1000P * mlcanopy_inst__trleaf_leaf[p - 1, ic - 1, il - 1] / mlcanopy_inst__lsc_profile[p - 1, ic - 1]
                        b = mlpftcon__capac_spa[patch__itype[p - 1] - 0] / mlcanopy_inst__lsc_profile[p - 1, ic - 1]
                        dy = (a - y0) * (1.0 - jnp.exp(-(dtime / b)))
                        mlcanopy_inst__lwp_leaf = mlcanopy_inst__lwp_leaf.at[p - 1, ic - 1, il - 1].set(y0 + dy)
                        return (y0, a, b, dy, mlcanopy_inst__lwp_leaf)

                    def _false_1(_c):
                        y0, a, b, dy, mlcanopy_inst__lwp_leaf = _c
                        mlcanopy_inst__lwp_leaf = mlcanopy_inst__lwp_leaf.at[p - 1, ic - 1, il - 1].set(0.0)
                        return (y0, a, b, dy, mlcanopy_inst__lwp_leaf)
                    y0, a, b, dy, mlcanopy_inst__lwp_leaf = lax.cond(mlcanopy_inst__dpai_profile[p - 1, ic - 1] > 0.0, _true_1, _false_1, (y0, a, b, dy, mlcanopy_inst__lwp_leaf))
                    return (y0, a, b, dy, mlcanopy_inst__lwp_leaf)

                def _false_2(_c):
                    y0, a, b, dy, mlcanopy_inst__lwp_leaf = _c
                    return (y0, a, b, dy, mlcanopy_inst__lwp_leaf)
                y0, a, b, dy, mlcanopy_inst__lwp_leaf = lax.cond(ic < mlcanopy_inst__ncan_canopy[p - 1] + 1, _true_2, _false_2, (y0, a, b, dy, mlcanopy_inst__lwp_leaf))
                return (y0, a, b, dy, mlcanopy_inst__lwp_leaf)
            y0, a, b, dy, mlcanopy_inst__lwp_leaf = lax.fori_loop(1, mlcanopy_inst__dpai_profile.shape[1] + 1, _body_3, (y0, a, b, dy, mlcanopy_inst__lwp_leaf))
            return (p, y0, a, b, dy, mlcanopy_inst__lwp_leaf)

        def _false_4(_c):
            p, y0, a, b, dy, mlcanopy_inst__lwp_leaf = _c
            return (p, y0, a, b, dy, mlcanopy_inst__lwp_leaf)
        p, y0, a, b, dy, mlcanopy_inst__lwp_leaf = lax.cond(fp < num_filter + 1, _true_4, _false_4, (p, y0, a, b, dy, mlcanopy_inst__lwp_leaf))
        return (p, y0, a, b, dy, mlcanopy_inst__lwp_leaf)
